-- ⚙️ CONFIG — tweak these to move the level up/down/left/right
local DEPTH_OFFSET = Vector3.new(
    0,   -- X shift (left/right)
    -40, -- Y shift (NEGATIVE = deeper underground; -40 = 40 studs below surface)
    0    -- Z shift (forward/backward)
)
local PARENT_FOLDER_NAME = "UndergroundBlocks"
local SPAWN_BATCH_SIZE = 50 -- build in chunks to avoid server freeze

-- Build function
local function buildUnderground(player)
    -- Clean up old blocks if they exist (so clicking twice doesn't duplicate)
    local existing = Workspace:FindFirstChild(PARENT_FOLDER_NAME)
    if existing then existing:Destroy() end
    
    local folder = Instance.new("Folder")
    folder.Name = PARENT_FOLDER_NAME
    folder.Parent = Workspace
    
    local created = 0
    local total = #LEVEL_DATA
    
    -- Spawn in batches so server doesn't hang
    for i, data in ipairs(LEVEL_DATA) do
        local part = Instance.new("Part")
        part.Name = data.Name or ("Block_"..i)
        part.Size = data.Size
        part.CFrame = data.CFrame + DEPTH_OFFSET -- ✨ shifts everything underground
        part.Material = data.Material
        part.Anchored = data.Anchored
        part.CanCollide = data.CanCollide
        if data.Transparency then part.Transparency = data.Transparency end
        if data.Color3 then part.Color = data.Color3 end
        part.Parent = folder
        
        created += 1
        
        -- Yield every N parts to keep server responsive
        if i % SPAWN_BATCH_SIZE == 0 then
            task.wait()
        end
    end
    
    print(("[Underground] %s spawned %d blocks at offset (%.1f, %.1f, %.1f)")
        :format(player.Name, created, DEPTH_OFFSET.X, DEPTH_OFFSET.Y, DEPTH_OFFSET.Z))
end

-- Listen for button clicks
event.OnServerEvent:Connect(buildUnderground)
